public static GUPPriceComponentCodePriceAttributeGroupSelection find(RecId _recId, boolean _update = false)
{
    GUPPriceComponentCodePriceAttributeGroupSelection  pricingAttributeGroupSelection;

    pricingAttributeGroupSelection.selectForUpdate(_update);

    if (_recId)
    {
        select firstonly pricingAttributeGroupSelection
            where pricingAttributeGroupSelection.RecId == _recId;
    }

    return pricingAttributeGroupSelection;
}

internal boolean checkSourceLevel()
{
    boolean ret = true;

    GUPPricingAttributeGroup selectionGroup = GUPPricingAttributeGroup::find(this.PriceAttributeGroup);

    if (selectionGroup.SourceLevel != this.SourceLevel)
    {
        ret = checkFailed("@GlobalUnifiedPricing:SourceLevelNotMatchedError");
    }

    return ret;
}

internal boolean checkPriority()
{
    boolean ret = true;

    if (this.Priority < 0 || this.Priority > 999)
    {
        ret = checkFailed("@GlobalUnifiedPricing:SelectionPriorityOutOfRangeError");
    }

    return ret;
}

public boolean validateWrite()
{
    boolean ret = super();

    ret = ret && this.checkSourceLevel();
    ret = ret && this.checkPriority();

    if (ret && this.RecId && this.orig().PriceAttributeGroup != this.PriceAttributeGroup)
    {
        ret = this.checkGroupCombinationForPriceDiscTable()
            && this.checkGroupCombinationForPriceAdjustment();
    }

    return ret;
}

private void updateGroupCombinationsOnUpdateGroupSelection()
{
    if (this.orig().PriceAttributeGroup != this.PriceAttributeGroup || this.orig().Priority != this.Priority)
    {
        GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

        groupCombination.selectForUpdate(true);

        if (this.SourceLevel == GUPPricingAttributeSourceLevel::Header)
        {
            while select groupCombination where
                groupCombination.PriceComponentCode == this.PriceComponentCode
                    && groupCombination.HeaderPriceAttributeGroup == this.orig().PriceAttributeGroup
            {
                groupCombination.HeaderPriceAttributeGroup = this.PriceAttributeGroup;
                groupCombination.initPriority(this);
                groupCombination.initName();
                groupCombination.update();
            }
        }
        else
        {
            while select groupCombination where
                groupCombination.PriceComponentCode == this.PriceComponentCode
                    && groupCombination.LinePriceAttributeGroup == this.orig().PriceAttributeGroup
            {
                groupCombination.LinePriceAttributeGroup = this.PriceAttributeGroup;
                groupCombination.initPriority(this);
                groupCombination.initName();
                groupCombination.update();
            }
        }

    }
}

private void updateGroupCombinationsOnInsertGroupSelection()
{
    GUPPriceComponentCode                                componentCode;
    GUPPriceComponentCodePriceAttributeGroupCombination  groupCombination;
    GUPPriceComponentCodePriceAttributeGroupSelection    groupSelection;
    GUPPricingAttributeSourceLevel                       combiningSourceLevel;

    boolean isHeader = this.SourceLevel == GUPPricingAttributeSourceLevel::Header;
    componentCode = GUPPriceComponentCode::find(this.PriceComponentCode);
    combiningSourceLevel = isHeader ? GUPPricingAttributeSourceLevel::Line : GUPPricingAttributeSourceLevel::Header;

    while select groupSelection
        where groupSelection.PriceComponentCode == this.PriceComponentCode
            && groupSelection.SourceLevel == combiningSourceLevel
    {
        // Insert combinations on current selection to insert.
        groupCombination.PriceComponentCode                  = this.PriceComponentCode;
        groupCombination.HeaderGroupAll                      = GUPGroupAll::Group;
        groupCombination.HeaderPriceAttributeGroup           = isHeader ? this.PriceAttributeGroup : groupSelection.PriceAttributeGroup;
        groupCombination.LineGroupAll                        = GUPGroupAll::Group;
        groupCombination.LinePriceAttributeGroup             = isHeader ? groupSelection.PriceAttributeGroup : this.PriceAttributeGroup;
        groupCombination.insert();
    }

    if ((!isHeader && componentCode.HeaderPriceAttributeGroupAllEnabled) ||
         (isHeader && componentCode.LinePriceAttributeGroupAllEnabled))
    {
        // If inserting header group while line "all" is enabled, insert such combination,
        // (same applies for inserting line group while header "all" is enabled).
        groupCombination.PriceComponentCode                  = this.PriceComponentCode;
        groupCombination.HeaderGroupAll                      = isHeader ? GUPGroupAll::Group : GUPGroupAll::All;
        groupCombination.HeaderPriceAttributeGroup           = isHeader ? this.PriceAttributeGroup : 0;
        groupCombination.LineGroupAll                        = isHeader ? GUPGroupAll::All : GUPGroupAll::Group;
        groupCombination.LinePriceAttributeGroup             = isHeader ? 0 : this.PriceAttributeGroup;
        groupCombination.insert();
    }
}

private void updateGroupCombinationsOnDeleteGroupSelection()
{
    GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

    // Delete all combinations referencing the record to delete.
    if (this.SourceLevel == GUPPricingAttributeSourceLevel::Header)
    {
        delete_from groupCombination
            where groupCombination.HeaderPriceAttributeGroup == this.PriceAttributeGroup
                && groupCombination.PriceComponentCode == this.PriceComponentCode;
    }
    else if (this.SourceLevel == GUPPricingAttributeSourceLevel::Line)
    {
        delete_from groupCombination
            where groupCombination.LinePriceAttributeGroup == this.PriceAttributeGroup
                && groupCombination.PriceComponentCode == this.PriceComponentCode;
    }
}

public void update()
{
    ttsbegin;

    if (GUPPriceComponentCode::find(this.PriceComponentCode).MaintenanceMode == GUPPriceComponentCodeMaintenanceMode::Separate)
    {
        this.updateGroupCombinationsOnUpdateGroupSelection();
        GUPPriceEngineJournalSearchEngine::expirePriority();
    }

    super();

    ttscommit;
}

public void insert()
{
    ttsbegin;

    super();

    if (GUPPriceComponentCode::find(this.PriceComponentCode).MaintenanceMode == GUPPriceComponentCodeMaintenanceMode::Separate)
    {
        this.updateGroupCombinationsOnInsertGroupSelection();
        GUPPriceEngineJournalSearchEngine::expirePriority();
    }

    ttscommit;
}

public void delete()
{
    ttsbegin;

    if (GUPPriceComponentCode::find(this.PriceComponentCode).MaintenanceMode == GUPPriceComponentCodeMaintenanceMode::Separate)
    {
        this.updateGroupCombinationsOnDeleteGroupSelection();
    }

    super();

    ttscommit;
}

    public void moveUp()
    {
        GUPPriceComponentCodePriceAttributeGroupSelection priceComponentCodePriceAttributeGroupSelection;

        select forupdate firstonly Priority from priceComponentCodePriceAttributeGroupSelection
            order by Priority desc
            where priceComponentCodePriceAttributeGroupSelection.PriceComponentCode == this.PriceComponentCode
                && priceComponentCodePriceAttributeGroupSelection.SourceLevel == this.SourceLevel
				&& priceComponentCodePriceAttributeGroupSelection.Priority > this.Priority;


        if (priceComponentCodePriceAttributeGroupSelection)
        {
            this.swapPriority(priceComponentCodePriceAttributeGroupSelection);
        }
    }

    public void moveDown()
    {
        GUPPriceComponentCodePriceAttributeGroupSelection priceComponentCodePriceAttributeGroupSelection;

        select forupdate firstonly Priority from priceComponentCodePriceAttributeGroupSelection
            order by Priority asc
            where priceComponentCodePriceAttributeGroupSelection.PriceComponentCode == this.PriceComponentCode
				&& priceComponentCodePriceAttributeGroupSelection.SourceLevel == this.SourceLevel
				&& priceComponentCodePriceAttributeGroupSelection.Priority < this.Priority;

        if (priceComponentCodePriceAttributeGroupSelection)
        {
            this.swapPriority(priceComponentCodePriceAttributeGroupSelection);
        }
    }

private void swapPriority(GUPPriceComponentCodePriceAttributeGroupSelection _priceComponentCodePriceAttributeGroupSelection)
{
    int newPriority;

    ttsbegin;
    newPriority = _priceComponentCodePriceAttributeGroupSelection.Priority;
    _priceComponentCodePriceAttributeGroupSelection.Priority = this.Priority;
    _priceComponentCodePriceAttributeGroupSelection.update();
    this.Priority = newPriority;
    this.update();
    ttscommit;
}

public boolean validateDelete()
{
    boolean ret;

    ret = super();

    return ret 
        && this.checkGroupCombinationForPriceDiscTable()
        && this.checkGroupCombinationForPriceAdjustment();
}

private boolean checkGroupCombinationForPriceDiscTable()
{
    boolean ret = true;

    GUPPriceComponentCode priceComponentCode = GUPPriceComponentCode::find(this.PriceComponentCode);
    if (priceComponentCode.MaintenanceMode == GUPPriceComponentCodeMaintenanceMode::Separate
        && priceComponentCode.PriceComponent == GUPPriceComponent::SalesTradeAgreement)
    {
        GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;
        PriceDiscTable priceDiscTable;

        select firstonly RecId from groupCombination
            where groupCombination.PriceComponentCode == this.PriceComponentCode
                && ((groupCombination.HeaderPriceAttributeGroup == this.orig().PriceAttributeGroup
                        && this.SourceLevel == GUPPricingAttributeSourceLevel::Header)
                    ||(groupCombination.LinePriceAttributeGroup == this.orig().PriceAttributeGroup
                        && this.SourceLevel == GUPPricingAttributeSourceLevel::Line))
            join RecId from priceDiscTable
                where priceDiscTable.PRICECOMPONENTCOMBINATION == groupCombination.RecId;

        if (groupCombination.RecId)
        {
            ret = checkFailed("@GlobalUnifiedPricing:GroupSelectionCannotBeModified");
        }
    }

    return ret;
}

private boolean checkGroupCombinationForPriceAdjustment()
{
    boolean ret = true;

    GUPPriceComponentCode priceComponentCode = GUPPriceComponentCode::find(this.PriceComponentCode);
    if (priceComponentCode.MaintenanceMode == GUPPriceComponentCodeMaintenanceMode::Separate
        && priceComponentCode.PriceComponent == GUPPriceComponent::PriceMarginComponentAdjustment)
    {
        if (this.SourceLevel == GUPPricingAttributeSourceLevel::Header)
        {
            GUPMarginComponentPriceAdjustment priceAdjustment;
            GUPPricingRule pricingRule;
            select firstonly RecId from priceAdjustment
                join RecId from pricingRule 
                where priceadjustment.HeaderPricingRule == pricingRule.RecId
                    && priceAdjustment.MarginComponentCode == this.PriceComponentCode
                    && pricingRule.PriceAttributeGroup == this.PriceAttributeGroup;

            if (priceAdjustment.RecId)
            {
                ret = checkFailed("@GlobalUnifiedPricing:GroupSelectionCannotBeModifiedForPriceAdjustment");
            }
        }

        if (ret)
        {
            GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;
            GUPMarginComponentPriceAdjustmentLine priceAdjustmentLine;

            select firstonly RecId from groupCombination
            where groupCombination.PriceComponentCode == this.PriceComponentCode
                && ((groupCombination.HeaderPriceAttributeGroup == this.orig().PriceAttributeGroup
                        && this.SourceLevel == GUPPricingAttributeSourceLevel::Header)
                    ||(groupCombination.LinePriceAttributeGroup == this.orig().PriceAttributeGroup
                        && this.SourceLevel == GUPPricingAttributeSourceLevel::Line))
            join RecId from priceAdjustmentLine
                where priceAdjustmentLine.PriceAttributeGroupCombinationRecId == groupCombination.RecId;

            if (groupCombination.RecId)
            {
                ret = checkFailed("@GlobalUnifiedPricing:GroupSelectionCannotBeModifiedForPriceAdjustmentLine");
            }
        }
    }

    return ret;
}
